const current=document.body.dataset.page||location.pathname.split('/').pop().replace('.html','')||'home';
const nav=[['index.html','Home','home'],['about.html','About','about'],['membership.html','Membership','membership'],['directory.html','Directory','directory'],['events.html','Events','events'],['news.html','News','news'],['contact.html','Contact','contact']];
const header=document.querySelector('[data-header]');
if(header){header.className='topbar';header.innerHTML=`<div class="shell"><a class="wordmark" href="index.html" aria-label="SLIID home"><strong>SLIID</strong><span>Sri Lanka Institute of Interior Designers</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav" aria-label="Open navigation"><span></span><span></span><span></span></button><nav class="mainnav" id="site-nav" aria-label="Main navigation">${nav.map(([href,label,key])=>`<a href="${href}"${current===key?' aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="join-btn" href="apply.html">Join SLIID →</a></div>`}
const footer=document.querySelector('[data-footer]');
if(footer){footer.className='site-footer';footer.innerHTML=`<div class="shell"><div class="footer-grid"><div class="footer-mark"><a class="wordmark" href="index.html"><strong>SLIID</strong><span>Sri Lanka Institute of Interior Designers</span></a><div class="footer-tag">People · Spaces · A Better Sri Lanka</div></div><div class="footer-col"><b>Explore</b><a href="about.html">About</a><a href="membership.html">Membership</a><a href="directory.html">Directory</a><a href="events.html">Events</a><a href="news.html">News</a></div><div class="footer-col"><b>Resources</b><a href="governance.html">Governance</a><a href="education.html">Professional learning</a><a href="publications.html">Publications</a><a href="awards.html">Awards</a></div><div class="footer-col"><b>Connect</b><span>Colombo, Sri Lanka</span><a href="contact.html">Contact the Institute</a><a href="apply.html">Become a member</a></div></div><div class="copyright"><span>© ${new Date().getFullYear()} Sri Lanka Institute of Interior Designers. All rights reserved.</span><span>Established under Act No. 2 of 1998</span></div></div>`}
const menuButton=document.querySelector('.menu-toggle');const navigation=document.querySelector('#site-nav');if(menuButton&&navigation){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));navigation.classList.toggle('open',!open)})}
if(current==='membership')document.querySelectorAll('a').forEach(a=>{if(/apply for membership/i.test(a.textContent))a.href='apply.html'});

const esc=value=>String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const date=value=>value?new Intl.DateTimeFormat('en-LK',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(value.replace(' ','T'))):'';
async function api(path,options={}){if(!window.SLIID_API_BASE)throw new Error('Backend connection has not been configured yet.');const response=await fetch(`${window.SLIID_API_BASE.replace(/\/$/,'')}/api.php?resource=${path}`,options);const data=await response.json().catch(()=>({ok:false,message:'Invalid server response.'}));if(!response.ok||!data.ok)throw new Error(data.message||'Request failed.');return data;}
async function initBackend(){
  try{const cfg=await fetch('api-config.json',{cache:'no-store'}).then(r=>r.ok?r.json():{});window.SLIID_API_BASE=cfg.apiBase||'';}catch{window.SLIID_API_BASE=''}
  const connected=Boolean(window.SLIID_API_BASE);
  document.documentElement.dataset.backend=connected?'connected':'pending';
  if(current==='contact'){const form=document.querySelector('.form');if(form){const fields=form.querySelectorAll('input,select,textarea');fields[0]?.setAttribute('name','name');fields[1]?.setAttribute('name','email');fields[2]?.setAttribute('name','subject');fields[3]?.setAttribute('name','message');form.addEventListener('submit',async event=>{event.preventDefault();const note=form.querySelector('.form-note');const button=form.querySelector('button');button.disabled=true;note.textContent='Sending…';try{const data=Object.fromEntries(new FormData(form));const result=await api('contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});note.textContent=result.message;form.reset();}catch(error){note.textContent=error.message;}finally{button.disabled=false;}})}}
  if(current==='apply'){const form=document.querySelector('#membership-application');if(form)form.addEventListener('submit',async event=>{event.preventDefault();const note=form.querySelector('.form-note');const button=form.querySelector('button');button.disabled=true;note.textContent='Submitting…';try{const result=await api('membership-applications',{method:'POST',body:new FormData(form)});note.textContent=result.message;form.reset();}catch(error){note.textContent=error.message;}finally{button.disabled=false;}})}
  if(!connected)return;
  if(current==='directory')initDirectory();
  if(current==='news')loadNews();
  if(current==='events')loadEvents();
  if(current==='publications')loadPublications();
}
async function initDirectory(){const form=document.querySelector('.filter-bar');const grid=document.querySelector('.member-grid');if(!form||!grid)return;const load=async()=>{const [q,category,specialisation,location]=[...form.querySelectorAll('input,select')].map(x=>x.value);const params=new URLSearchParams({limit:'48'});if(q)params.set('q',q);if(category&&!category.startsWith('All'))params.set('category',category.toLowerCase());if(location&&!location.startsWith('All'))params.set('location',location);try{const result=await api(`members&${params}`);grid.innerHTML=result.data.length?result.data.map(member=>`<article class="member">${member.image_url?`<img class="member-photo" src="${esc(member.image_url)}" alt="${esc(member.name)}">`:'<div class="member-placeholder">SLIID</div>'}<div class="member-body"><h3>${esc(member.name)}</h3><small>${esc(member.category.replace('_',' '))} member</small><p>${esc(member.membership_number)}</p><p>${esc(member.location||'Sri Lanka')} · ${esc(member.specialisations||'Interior Design')}</p>${member.website?`<a class="text-link" target="_blank" rel="noopener" href="${esc(member.website)}">View website →</a>`:''}</div></article>`).join(''):'<p>No matching members were found.</p>';}catch(error){grid.insertAdjacentHTML('beforebegin',`<p class="api-error">${esc(error.message)}</p>`);}};form.addEventListener('submit',event=>{event.preventDefault();load()});load();}
async function loadNews(){const grid=document.querySelector('.news-grid');if(!grid)return;try{const result=await api('news&limit=12');if(!result.data.length)return;grid.innerHTML=result.data.map(item=>`<article class="card"><img class="card-img" src="${esc(item.image_url||'assets/contact-interior.webp')}" alt=""><div class="card-body"><span class="meta">${esc(item.category)} · ${esc(date(item.published_at))}</span><h3>${esc(item.title)}</h3><p>${esc(item.excerpt||'')}</p></div></article>`).join('');}catch{} }
async function loadEvents(){const grid=document.querySelector('.cards.four,.cards');if(!grid)return;try{const result=await api('events&limit=12');if(!result.data.length)return;grid.innerHTML=result.data.map(item=>`<article class="card"><img class="card-img" src="${esc(item.image_url||'assets/events-interior.webp')}" alt=""><div class="card-body"><span class="meta">Event</span><h3>${esc(item.title)}</h3><p>${esc(date(item.starts_at))} · ${esc(item.venue||'To be confirmed')}</p>${item.registration_url?`<a class="text-link" href="${esc(item.registration_url)}" target="_blank" rel="noopener">Register →</a>`:''}</div></article>`).join('');}catch{} }
async function loadPublications(){const grid=document.querySelector('.cards');if(!grid)return;try{const result=await api('publications&limit=30');if(!result.data.length)return;grid.innerHTML=result.data.map(item=>`<article class="card"><div class="card-body"><span class="meta">${esc(item.category)}</span><h3>${esc(item.title)}</h3><p>${esc(item.description||'')}</p>${item.file_url||item.external_url?`<a class="text-link" href="${esc(item.file_url||item.external_url)}" target="_blank" rel="noopener">Open publication →</a>`:''}</div></article>`).join('');}catch{} }
initBackend();
